import sys, math
MOD=998244353

def factor(n):
    r=[]; d=2
    while d*d<=n:
        if n%d==0:
            c=0
            while n%d==0:n//=d;c+=1
            r.append((d,c))
        d+=1
    if n>1:r.append((n,1))
    return r

def calc(p, aa):
    n=len(aa)+1
    ds=[[e-2*x for x in range(e+1)] for e in aa]
    pw=[1]
    for _ in range(sum(aa)+2): pw.append(pw[-1]*p%MOD)
    # R[j]: nonnegative paths from j to N, weighted heights after j
    R=[0]*n
    f={0:1}
    R[n-1]=1
    for j in range(n-2,-1,-1):
        nf={}
        for h,v in f.items():
            # h is height at next vertex; current height k=h-d
            for d in ds[j]:
                k=h-d
                if k>=0:
                    nf[k]=(nf.get(k,0)+v*pw[h])%MOD
        f=nf; R[j]=f.get(0,0)
    # L[j], paths ending at j as first minimum; prior vertices strictly positive
    L=[0]*n; L[0]=1
    # H_j(h): paths from j backwards, prior vertices nonnegative, with vertex 1 strict
    hdict={h:1 for h in range(1,sum(aa)+1)}
    for j in range(1,n):
        nf={}
        for h,v in hdict.items():
            for d in ds[j-1]:
                k=h-d
                if k>=0:
                    nf[h]=(nf.get(h,0)+v*pw[k])%MOD
        hdict=nf; L[j]=hdict.get(0,0)
    return sum(L[j]*R[j] for j in range(n))%MOD

def main():
    data=list(map(int,sys.stdin.buffer.read().split())); n=data[0]; a=data[1:]
    fs={}
    for x in a:
        for p,e in factor(x): fs.setdefault(p,[0]* (n-1)); fs[p][a.index(x) if False else 0]=0
    ans=1
    for p in set(q for x in a for q,e in factor(x)):
        ex=[]
        for x in a:
            z=0
            while x%p==0:x//=p;z+=1
            ex.append(z)
        ans=ans*calc(p,ex)%MOD
