MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]
    mx = max(a)

    phi = list(range(mx + 1))
    for p in range(2, mx + 1):
        if phi[p] == p:
            for v in range(p, mx + 1, p):
                phi[v] -= phi[v] // p

    divisors = [[] for _ in range(mx + 1)]
    for d in range(1, mx + 1):
        for v in range(d, mx + 1, d):
            divisors[v].append(d)

    total = [0] * (mx + 1)
    ans = 0
    weight = 1
    out = []
    ph = phi
    cnt = total
    mod = MOD
    for x in a:
        s = 0
        for d in divisors[x]:
            s += ph[d] * cnt[d]
        ans = (ans + ans + s) % mod
        out.append(str(ans))
        for d in divisors[x]:
            z = cnt[d] + weight
            if z >= mod:
                z -= mod
            cnt[d] = z
        weight += weight
        if weight >= mod:
            weight -= mod
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
