import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    values = data[1:]
    limit = max(values, default=1)

    spf = list(range(limit + 1))
    if limit >= 1:
        spf[1] = 1
    for i in range(2, int(limit ** 0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, limit + 1, i):
                if spf[j] == j:
                    spf[j] = i

    result = 0
    for value in values:
        omega = 0
        while value > 1:
            value //= spf[value]
            omega += 1
        result ^= omega

    print("Anna" if result else "Bruno")

if __name__ == "__main__":
    main()

