import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)
    try:
        n = next(it)
    except StopIteration:
        return
    m = next(it)
    q = next(it)

    edges = [(next(it) - 1, next(it) - 1, next(it)) for _ in range(m)]
    queries = []
    closed = [False] * m
    for _ in range(q):
        t = next(it)
        if t == 1:
            k = next(it) - 1
            queries.append((1, k))
            closed[k] = True
        else:
            queries.append((2, next(it) - 1, next(it) - 1))

    inf = 10 ** 30
    dist = [[inf] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for k, (u, v, w) in enumerate(edges):
        if not closed[k]:
            dist[u][v] = w
            dist[v][u] = w

    # All roads which are never closed are present initially.
    for k in range(n):
        rk = dist[k]
        for i in range(n):
            ri = dist[i]
            via = ri[k]
            if via < inf:
                dist[i] = [min(x, via + y) for x, y in zip(ri, rk)]

    answers = []
    # In reverse, closing a road is opening it.  Thus only additions remain.
    for query in reversed(queries):
        if query[0] == 2:
            value = dist[query[1]][query[2]]
            answers.append(-1 if value >= inf else value)
        else:
            u, v, w = edges[query[1]]
            row_u = dist[u][:]
            row_v = dist[v][:]
            for i in range(n):
                row = dist[i]
                via_u = row[u] + w
                via_v = row[v] + w
                dist[i] = [min(old, via_u + from_v, via_v + from_u)
                           for old, from_v, from_u in zip(row, row_v, row_u)]

    sys.stdout.write("\n".join(map(str, reversed(answers))))

if __name__ == "__main__":
    main()

