        MOD = 10**9 + 7
        n = len(s)
        C = [[0] * (n + 1) for _ in range(n + 1)]
        C[0][0] = 1
        for i in range(1, n + 1):
            C[i][0] = C[i][i] = 1
            for j in range(1, i):
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

        good = [False] * (n + 1)
        for c in range(1, n + 1):
            if c == 1:
                good[c] = True
            else:
                value = c
