import heapq

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    g = [x.decode() for x in data[1:]]

    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[0] * 26 for _ in range(n)]
    for i in range(n):
        for j, ch in enumerate(g[i]):
            if ch != '-':
                c = ord(ch) - 97
                incoming[j][c].append(i)
                outgoing[i][c] |= 1 << j

    inf = 10**9
    dist = [[inf] * n for _ in range(n)]
    unvisited = [(1 << n) - 1 for _ in range(n)]
    heap = []

    for i in range(n):
        dist[i][i] = 0
        unvisited[i] &= ~(1 << i)
        heapq.heappush(heap, (0, i, i))

    for i in range(n):
        for j, ch in enumerate(g[i]):
            if ch != '-' and dist[i][j] > 1:
                dist[i][j] = 1
                unvisited[i] &= ~(1 << j)
                heapq.heappush(heap, (1, i, j))

    while heap:
        cur, u, v = heapq.heappop(heap)
        if dist[u][v] != cur:
            continue
        newdist = cur + 2
        for c in range(26):
            targets = outgoing[v][c]
            if not targets:
                continue
            for i in incoming[u][c]:
                fresh = targets & unvisited[i]
                while fresh:
                    bit = fresh & -fresh
                    fresh -= bit
                    j = bit.bit_length() - 1
                    unvisited[i] ^= bit
                    dist[i][j] = newdist
                    heapq.heappush(heap, (newdist, i, j))

    out = []
    for row in dist:
        out.append(' '.join(str(x if x < inf else -1) for x in row))
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

