import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, x = data[0], data[1]
    vals = data[2:]
    u = vals[::2]
    d = vals[1::2]

    initial_total = sum(u) + sum(d)
    upper_h = min(a + b for a, b in zip(u, d))

    def feasible(h):
        # Possible interval of the final upper-tooth length at the current index.
        lo = max(0, h - d[0])
        hi = min(u[0], h)
        if lo > hi:
            return False

        for i in range(1, n):
            lo = max(0, h - d[i], lo - x)
            hi = min(u[i], h, hi + x)
            if lo > hi:
                return False
        return True

    left, right = 0, upper_h + 1
    while right - left > 1:
        mid = (left + right) // 2
        if feasible(mid):
            left = mid
        else:
            right = mid

    print(initial_total - n * left)

