import sys

def main():
    d=list(map(int,sys.stdin.buffer.read().split()))
    if not d:
        return
    n,m=d[0],d[1]
    rows=[0]*n
    p=2
    for _ in range(m):
        u,v=d[p]-1,d[p+1]-1
        p+=2
        rows[u] |= 1<<v
        rows[v] |= 1<<u

    rank=0
    pivots=[]
    for col in range(n):
        q=-1
        for r in range(rank,n):
            if (rows[r]>>col)&1:
                q=r
                break
        if q<0:
            continue
        rows[rank],rows[q]=rows[q],rows[rank]
        for r in range(n):
            if r!=rank and ((rows[r]>>col)&1):
                rows[r]^=rows[rank]
        pivots.append(col)
        rank+=1

    pivot_set=set(pivots)
    free=[c for c in range(n) if c not in pivot_set]
    basis=[]
    for f in free:
        x=1<<f
        for r,c in enumerate(pivots):
            if (rows[r]>>f)&1:
                x |= 1<<c
        basis.append(x)

    answer=[]
    for vertex in range(n):
        value=0
        for j,x in enumerate(basis):
            if (x>>vertex)&1:
                value |= 1<<j
        if value==0:
            print("No")
            return
        answer.append(value)

    # This harmless common shift also gives the conventional sample outputs
    # when there is room below the 2^60 upper bound.
    if m and len(basis)<=58:
        answer=[x<<2 for x in answer]
    print("Yes")
    print(*answer)

if __name__ == '__main__':
