class Solution:
 def lenOfVDiagonal(self, grid):
  n=len(grid); m=len(grid[0]); N=n*m
  ds=((1,1),(1,-1),(-1,-1),(-1,1))
  B=[[array('H',[0])*N for _ in range(2)] for _ in range(4)]
  for d,(dr,dc) in enumerate(ds):
   rs=range(n-1,-1,-1) if dr==1 else range(n)
   cs=range(m-1,-1,-1) if dc==1 else range(m)
   for r in rs:
    for c in cs:
