from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        CAP = 10**15 + 1
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(CAP, fact[i - 1] * i)

        def ways(odd: int, even: int, next_parity: int) -> int:
            length = odd + even
            if next_parity == 1:
                needed_odd = (length + 1) // 2
                needed_even = length // 2
            else:
                needed_even = (length + 1) // 2
                needed_odd = length // 2
            if odd != needed_odd or even != needed_even:
                return 0
            return min(CAP, fact[odd] * fact[even])

        remaining = list(range(1, n + 1))
        answer = []
        required = None

        for _ in range(n):
            selected = None
            for i, value in enumerate(remaining):
                if required is not None and value % 2 != required:
                    continue
                odd = sum(y % 2 for j, y in enumerate(remaining) if j != i)
                even = len(remaining) - 1 - odd
                count = ways(odd, even, 1 - (value % 2))
                if k > count:
                    k -= count
                else:
                    selected = (i, value)
                    break

            if selected is None:
                return []
            index, value = selected
            answer.append(value)
            remaining.pop(index)
            required = 1 - (value % 2)

        return answer

