    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        powers = [1] * n
        for i in range(1, n):
            powers[i] = (powers[i - 1] * 10) % k

        coeff = []
        for i in range(m):
            j = n - 1 - i
            if i == j:
                coeff.append(powers[i])
            else:
                coeff.append((powers[i] + powers[j]) % k)

        # dp[i][r] says whether positions i and later can contribute
        # residue r modulo k.
        dp = [None] * (m + 1)
        dp[m] = bytearray([1] + [0] * (k - 1))
        for i in range(m - 1, -1, -1):
            c = coeff[i]
            following = dp[i + 1]
            possible = bytearray(k)
            for r in range(k):
                for digit in range(10):
                    if following[(r - digit * c) % k]:
                        possible[r] = 1
                        break
            dp[i] = possible

        result = []
        residue = 0
        for i, c in enumerate(coeff):
            lowest = 1 if i == 0 else 0
            for digit in range(9, lowest - 1, -1):
                needed = (-residue - digit * c) % k
                if dp[i + 1][needed]:
                    result.append(str(digit))
                    residue = (residue + digit * c) % k
                    break

        left = ''.join(result)
        if n % 2:
            return left + left[-2::-1]
        return left + left[::-1]

