class Solution:
 def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
  n=len(nums); INF=10**30; mn=[INF]*(4*n); lz=[0]*(4*n)
  def add(p,l,r,a,b,x):
   if a<=l and r<=b: mn[p]+=x; lz[p]+=x; return
   m=(l+r)//2
   if a<=m:add(p*2,l,m,a,b,x)
   if b>m:add(p*2+1,m+1,r,a,b,x)
   mn[p]=lz[p]+min(mn[p*2],mn[p*2+1])
  def put(p,l,r,x):
   if l==r: mn[p]=0;lz[p]=0;return
   m=(l+r)//2
   if x<=m:put(p*2,l,m,x)
   else:put(p*2+1,m+1,r,x)
   mn[p]=lz[p]+min(mn[p*2],mn[p*2+1])
  def find(p,l,r,lim,carry=0):
   if l>lim or mn[p]+carry>k:return lim+1
   if l==r:return l
   m=(l+r)//2; c=carry+lz[p]
   z=find(p*2,l,m,lim,c)
   return z if z<=lim else find(p*2+1,m+1,r,lim,c)
  st=[]; ans=0
  for r,a in enumerate(nums):
   start=r
   while st and st[-1][1]<=a:start=st.pop()[0]
   boundary=r
   i=len(st)-1
   while i>=0 and st[i][1]>a:
    s,v=st[i]; add(1,0,n-1,s,boundary-1,v-a); boundary=s; i-=1
   st.append((start,a)); put(1,0,n-1,r)
   q=find(1,0,n-1,r); ans+=r-q+1
  return ans

