import sys
from functools import cmp_to_key

def compare(x, y):
    # Functions with smaller ratio (A-1)/B are placed earlier,
    # hence are applied closer to the initial value.
    cross = (x[0] - 1) * y[1] - (y[0] - 1) * x[1]
    if cross < 0:
        return -1
    if cross > 0:
        return 1
    return 0

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    funcs = [tuple(data[i:i + 2]) for i in range(2, 2 + 2 * n, 2)]
    funcs.sort(key=cmp_to_key(compare))

    neg = -10**100
    dp = [neg] * (k + 1)
    dp[0] = 1
    for a, b in funcs:
        for j in range(k, 0, -1):
            if dp[j - 1] != neg:
                value = a * dp[j - 1] + b
                if value > dp[j]:
                    dp[j] = value
    print(dp[k])

if __name__ == '__main__':
    main()

