from array import array

class Solution:
    def maximumSubarrayXor(self, nums, queries):
        n = len(nums)
        score = [array('I', [0]) * n for _ in range(n)]
        best = [array('I', [0]) * n for _ in range(n)]

        for i, value in enumerate(nums):
            score[i][i] = value
            best[i][i] = value

        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                value = score[i][j - 1] ^ score[i + 1][j]
                score[i][j] = value
                current = best[i + 1][j]
                if best[i][j - 1] > current:
                    current = best[i][j - 1]
                if value > current:
                    current = value
                best[i][j] = current

        return [best[left][right] for left, right in queries]

