class Solution:
    def makeStringGood(self, s: str) -> int:
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        n = len(s)
        answer = n

        for k in range(1, n + 1):
            # (whether a letter was selected, surplus available to the right,
            #  whether any letter has been selected) -> maximum savings
            dp = {(0, 0, 0): 0}
            for x in cnt:
                nxt = {}
                for (selected, surplus, used), value in dp.items():
                    key = (0, x, used)
                    if value > nxt.get(key, -10**9):
                        nxt[key] = value

                    own = min(x, k)
                    incoming = min(surplus, k - own)
                    key = (1, x - own, 1)
                    value2 = value + 2 * own + incoming - k
                    if value2 > nxt.get(key, -10**9):
                        nxt[key] = value2
                dp = nxt
            answer = min(answer, n - max(dp.values()))

        return answer

