import sys
from functools import lru_cache

sys.setrecursionlimit(1_000_000)

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m, l = data[:3]
    values = data[3:]
    total = n + m + l
    all_mask = (1 << total) - 1
    initial_takahashi = (1 << n) - 1
    initial_aoki = ((1 << m) - 1) << n

    @lru_cache(maxsize=None)
    def win(hand0, hand1, turn):
        hand = hand0 if turn == 0 else hand1
        if hand == 0:
            return False

        table = all_mask ^ (hand0 | hand1)
        cards = hand
        while cards:
            played_bit = cards & -cards
            cards -= played_bit
            played = played_bit.bit_length() - 1
            remaining = hand ^ played_bit

            # The player may choose not to take a card.
            if turn == 0:
                if not win(remaining, hand1, 1):
                    return True
            else:
                if not win(hand0, remaining, 0):
                    return True

            # Or take any smaller card currently on the table.
            candidates = table
            while candidates:
                taken_bit = candidates & -candidates
                candidates -= taken_bit
                taken = taken_bit.bit_length() - 1
                if values[taken] < values[played]:
                    if turn == 0:
                        if not win(remaining | taken_bit, hand1, 1):
                            return True
                    else:
                        if not win(hand0, remaining | taken_bit, 0):
                            return True

        return False

    print("Takahashi" if win(initial_takahashi, initial_aoki, 0) else "Aoki")

if __name__ == "__main__":
    main()

