                return list(range(n + 1)) + [INF]
            pi = [0] * m
            j = 0
            for k in range(1, m):
                while j and t[k] != t[j]:
                    j = pi[j-1]
                if t[k] == t[j]:
                    j += 1
                pi[k] = j
            occ = [False] * (n + 1)
            j = 0
            for k, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j-1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    occ[k-m+1] = True
                    j = pi[j-1]
            nx = [INF] * (n + 2)
            for q in range(n, -1, -1):
                if occ[q]:
                    nx[q] = q
                else:
                    nx[q] = nx[q+1]
            return nx
        na, nb, nc = next_occ(a), next_occ(b), next_occ(c)
        la, lb, lc = len(a), len(b), len(c)
        ans = INF
        for i in range(n + 1):
            x = na[i]
            if x != i: continue
            y = nb[i + la]
            if y > n: continue
            z = nc[y + lb]
            if z <= n:
                ans = min(ans, z + lc - i)
        return -1 if ans == INF else ans

