class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        post = []
        stack = [(0, 0)]
        while stack:
            v, exiting = stack.pop()
            if not exiting:
                stack.append((v, 1))
                for u in reversed(children[v]):
                    stack.append((u, 0))
            else:
                post.append(v)

        size = [1] * n
        for v in post:
            if parent[v] != -1:
                size[parent[v]] += size[v]

        text = ''.join(s[v] for v in post)

        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and text[i-k] == text[i+k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and text[i-k-1] == text[i+k]:
                k += 1
            even[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        answer = [False] * n
        pos = 0
        for v in post:
            length = size[v]
            l = pos - length + 1
            r = pos
            if length & 1:
                answer[v] = odd[(l + r) // 2] >= length // 2 + 1
            else:
                answer[v] = even[(l + r + 1) // 2] >= length // 2
            pos += 1
        return answer

