import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        prime = [True] * 10000
        prime[0] = prime[1] = False
        for i in range(2, 100):
            if prime[i]:
                for j in range(i * i, 10000, i):
                    prime[j] = False

        if prime[n] or prime[m]:
            return -1

        width = len(str(n))
        inf = 10 ** 30
        dist = [inf] * 10000
        dist[n] = n
        heap = [(n, n)]

        while heap:
            cost, x = heapq.heappop(heap)
            if cost != dist[x]:
                continue
            if x == m:
                return cost

            place = 1
            for position in range(width):
                digit = (x // place) % 10

                if digit < 9:
                    y = x + place
                    leading_zero = (width > 1 and position == width - 1 and
                                    (y // place) % 10 == 0)
                    if not leading_zero and not prime[y]:
                        new_cost = cost + y
                        if new_cost < dist[y]:
                            dist[y] = new_cost
                            heapq.heappush(heap, (new_cost, y))

                if digit > 0:
                    y = x - place
                    leading_zero = (width > 1 and position == width - 1 and
                                    (y // place) % 10 == 0)
                    if not leading_zero and not prime[y]:
                        new_cost = cost + y
                        if new_cost < dist[y]:
                            dist[y] = new_cost
                            heapq.heappush(heap, (new_cost, y))

                place *= 10

        return -1

