class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        # Z-array: z[i] is the length of the common prefix of nums and nums[i:].
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        # good[i] means that the first part of length i is a prefix of
        # the second part, independently of where its end is chosen.
        good = [False] * n
        answer = 0
        for i in range(1, n - 1):
            if z[i] >= i:
                good[i] = True
                answer += n - i - 1

        # For a second part of length d, compare the two adjacent blocks.
        # A run of d equal offset-pairs identifies one valid starting split.
        for d in range(1, n // 2 + 1):
