from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        states = [(a, b) for a in range(3) for b in range(3) if a != b]
        INF = 10**30
        dp = [cost[0][a] + cost[n - 1][b] for a, b in states]

        for k in range(1, n // 2):
            left, right = k, n - 1 - k
            ndp = [INF] * 6
            for old, (prev_left, prev_right) in enumerate(states):
                base = dp[old]
                for new, (left_color, right_color) in enumerate(states):
                    if left_color != prev_left and right_color != prev_right:
                        value = (base + cost[left][left_color] +
                                 cost[right][right_color])
                        if value < ndp[new]:
                            ndp[new] = value
            dp = ndp

        return min(dp)

