class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        t = '1' + s + '1'
        runs = []
        i = 0
        while i < len(t):
            j = i
            while j < len(t) and t[j] == t[i]:
                j += 1
            runs.append((t[i], j - i))
            i = j

        ones = s.count('1')
        zero_lengths = [length for bit, length in runs if bit == '0']
        internal_ones = []
        for k in range(1, len(runs) - 1):
            if runs[k][0] == '1':
                internal_ones.append((runs[k - 1][1], runs[k][1], runs[k + 1][1]))

        if not internal_ones:
            return ones

        largest_zero = max(zero_lengths)
        shortest_one = min(item[1] for item in internal_ones)
        best_gain = largest_zero - shortest_one
        best_gain = max(best_gain,
                        max(left + right for left, _, right in internal_ones))
        return ones + max(0, best_gain)

